from fractions import Fraction

def gaussian_elimination(A):
    n = len(A)
    for i in range(n):
        # Find pivot row
        max_row = i
        for j in range(i+1, n):
            if abs(A[j][i]) > abs(A[max_row][i]):
                max_row = j
        A[i], A[max_row] = A[max_row], A[i]

        # Eliminate non-pivot elements
        for j in range(n):
            if i != j:
                factor = Fraction(A[j][i], A[i][i])
                for k in range(n+1):
                    A[j][k] -= factor * A[i][k]

    # Back-substitute to find solution
    x = [0] * n
    for i in range(n-1, -1, -1):
        x[i] = Fraction(A[i][n], A[i][i])
        for j in range(i-1, -1, -1):
            A[j][n] -= A[j][i] * x[i]
    return x

def matrix_multiply(A, B):
    n = len(A)
    C = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            for k in range(n):
                C[i][j] += A[i][k] * B[k][j]
    return C

def height_dpll(clauses):
    assignment = {}
    stack = []

    def backtrack():
        if all(l in assignment or -l in assignment for l in set.union(*clauses)):
            return True
        literal = next((l for l in set.union(*clauses) if l not in assignment and -l not in assignment), None)
        if literal is None:
            return False

        assignment[literal] = True
        stack.append(literal)

        if backtrack():
            return True

        del assignment[literal]
        stack.pop()

        assignment[-literal] = True
        stack.append(-literal)

        if backtrack():
            return True

        del assignment[-literal]
        stack.pop()

        return False

    return len(stack) if backtrack() else 0

